using Microsoft.EntityFrameworkCore;
using WhaleDeck.Domain.Entities;

namespace WhaleDeck.Infrastructure.Persistence;

public sealed partial class PlatformDbContext
{
    private static void ConfigureContainerAcls(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<ContainerAclIntent>(entity =>
        {
            entity.ToTable("container_acl_intents", table =>
            {
                table.HasCheckConstraint("ck_container_acl_requested_acl", "((command_json::jsonb->>'AclType' IN ('access','default') AND command_json::jsonb->>'ExpectedVersion' ~ '^[A-F0-9]{64}$' AND whaledeck_acl_entries_valid(command_json::jsonb->'Entries',command_json::jsonb->>'AclType'='default') AND command_json::jsonb->'Location'->>'ContainerId'=container_id AND command_json::jsonb->'Location'->>'InstanceId'=instance_id AND command_json::jsonb->'Location'->>'Path'=relative_path) IS TRUE)");
                table.HasCheckConstraint("ck_container_acl_planned_acl", "plan_json IS NULL OR ((plan_json::jsonb->'Command'=command_json::jsonb AND plan_json::jsonb->>'Kind' IN ('File','Directory') AND whaledeck_acl_entries_valid(plan_json::jsonb->'AccessAcl',FALSE) AND whaledeck_acl_entries_valid(plan_json::jsonb->'DefaultAcl',TRUE) AND whaledeck_acl_mode(plan_json::jsonb->'AccessAcl')=((plan_json::jsonb->'SourceIdentity'->>'Mode')::integer & 511) AND (plan_json::jsonb->>'TargetMode')::integer=CASE WHEN command_json::jsonb->>'AclType'='access' THEN whaledeck_acl_mode(command_json::jsonb->'Entries') ELSE (plan_json::jsonb->'SourceIdentity'->>'Mode')::integer & 511 END AND (plan_json::jsonb->'NoChange')=to_jsonb(command_json::jsonb->'Entries'=CASE WHEN command_json::jsonb->>'AclType'='access' THEN plan_json::jsonb->'AccessAcl' ELSE plan_json::jsonb->'DefaultAcl' END) AND (plan_json::jsonb->>'Kind'<>'File' OR command_json::jsonb->>'AclType'='access' AND plan_json::jsonb->'DefaultAcl'='[]'::jsonb)) IS TRUE)");
                table.HasCheckConstraint("ck_container_acl_receipt", "(receipt_json IS NULL AND receipt_hash IS NULL AND acl_confirmed IS NULL AND published_version IS NULL AND NOT history_verified AND history_digest IS NULL) OR ((receipt_json IS NOT NULL AND octet_length(receipt_json) BETWEEN 1 AND 65536 AND receipt_hash IS NOT NULL AND receipt_hash ~ '^[A-F0-9]{64}$' AND execution_job_id IS NOT NULL AND plan_json IS NOT NULL AND receipt_json::jsonb->>'State' IN ('Completed','Aborted','Unknown') AND jsonb_typeof(receipt_json::jsonb->'BindingCurrent')='boolean' AND jsonb_typeof(receipt_json::jsonb->'HistoryMayExist')='boolean' AND jsonb_typeof(receipt_json::jsonb->'HistoryVerified')='boolean' AND jsonb_typeof(receipt_json::jsonb->'Replayed')='boolean' AND ((receipt_json::jsonb->>'State'='Completed' AND acl_confirmed IS TRUE AND receipt_json::jsonb->'AclConfirmed'='true'::jsonb AND history_verified AND published_version=receipt_json::jsonb->>'Version' AND published_version ~ '^[A-F0-9]{64}$') OR (receipt_json::jsonb->>'State'='Aborted' AND acl_confirmed IS FALSE AND receipt_json::jsonb->'AclConfirmed'='false'::jsonb AND published_version IS NULL AND receipt_json::jsonb->>'Version'='' AND receipt_json::jsonb->'BindingCurrent'='false'::jsonb) OR (receipt_json::jsonb->>'State'='Unknown' AND acl_confirmed IS NULL AND receipt_json::jsonb->'AclConfirmed'='null'::jsonb AND published_version IS NULL AND receipt_json::jsonb->>'Version'='' AND receipt_json::jsonb->'BindingCurrent'='false'::jsonb))) IS TRUE)");
                table.HasCheckConstraint("ck_container_acl_receipt_binding", "receipt_json IS NULL OR ((receipt_json::jsonb->>'Id'=execution_job_id::text AND receipt_json::jsonb->>'ContainerId'=container_id AND receipt_json::jsonb->>'InstanceId'=instance_id AND receipt_json::jsonb->>'Fingerprint'=plan_json::jsonb->>'Fingerprint' AND receipt_json::jsonb->>'TargetProof'=plan_json::jsonb->>'TargetProof' AND receipt_json::jsonb->>'Kind'=plan_json::jsonb->>'Kind' AND receipt_json::jsonb->>'AclType'=command_json::jsonb->>'AclType' AND receipt_json::jsonb->'TargetMode'=plan_json::jsonb->'TargetMode' AND receipt_json::jsonb->'NoChange'=plan_json::jsonb->'NoChange' AND (receipt_json::jsonb->>'HistoryVerified')::boolean=history_verified AND (NOT (receipt_json::jsonb->>'HistoryMayExist')::boolean OR history_may_exist) AND receipt_json::jsonb->>'HistoryDigest'=COALESCE(history_digest,'') AND (state NOT IN ('Succeeded','Superseded') OR receipt_json::jsonb->>'State'='Completed' AND (receipt_json::jsonb->>'BindingCurrent')::boolean=(state='Succeeded')) AND (state<>'Unknown' OR receipt_json::jsonb->>'State'='Unknown') AND (execution_job_id IS NULL OR state NOT IN ('Canceled','Failed') OR receipt_json::jsonb->>'State'='Aborted')) IS TRUE)");
                table.HasCheckConstraint("ck_container_acl_state", "state IN ('Queued','Planning','Ready','Pending','Applying','Unknown','Succeeded','Superseded','Canceled','Failed','Expired','Acknowledged')");
                table.HasCheckConstraint("ck_container_acl_terminal", "(completed_at_utc IS NULL) = (state IN ('Queued','Planning','Ready','Pending','Applying','Unknown'))");
                table.HasCheckConstraint("ck_container_acl_identity", "id <> '00000000-0000-0000-0000-000000000000'::uuid AND idempotency_key <> '00000000-0000-0000-0000-000000000000'::uuid AND container_id ~ '^[a-f0-9]{64}$' AND octet_length(relative_path) BETWEEN 1 AND 4096 AND length(actor_subject) BETWEEN 1 AND 256 AND length(trace_id) BETWEEN 1 AND 128 AND octet_length(command_json) BETWEEN 1 AND 65536");
                table.HasCheckConstraint("ck_container_acl_lifetime", "created_at_utc > TIMESTAMPTZ '1970-01-01 00:00:00+00' AND planning_expires_at_utc = created_at_utc + INTERVAL '15 minutes' AND version >= 0");
                table.HasCheckConstraint("ck_container_acl_hashes", "login_binding ~ '^[A-F0-9]{64}$' AND owner_hash ~ '^[A-F0-9]{64}$' AND request_hash ~ '^[A-F0-9]{64}$' AND (published_version IS NULL OR published_version ~ '^[A-F0-9]{64}$')");
                table.HasCheckConstraint("ck_container_acl_plan", "(plan_json IS NULL AND plan_hash IS NULL AND ready_expires_at_utc IS NULL) OR (plan_json IS NOT NULL AND octet_length(plan_json) BETWEEN 1 AND 65536 AND plan_hash IS NOT NULL AND plan_hash ~ '^[A-F0-9]{64}$' AND ready_expires_at_utc IS NOT NULL AND ready_expires_at_utc > created_at_utc AND ready_expires_at_utc <= planning_expires_at_utc + INTERVAL '5 minutes')");
                table.HasCheckConstraint("ck_container_acl_execution", "(execution_job_id IS NULL AND confirmed_at_utc IS NULL AND execution_expires_at_utc IS NULL AND execution_hash IS NULL) OR (execution_job_id IS NOT NULL AND execution_job_id <> id AND execution_job_id <> '00000000-0000-0000-0000-000000000000'::uuid AND plan_json IS NOT NULL AND confirmed_at_utc IS NOT NULL AND confirmed_at_utc >= created_at_utc AND confirmed_at_utc < ready_expires_at_utc AND execution_expires_at_utc IS NOT NULL AND execution_expires_at_utc = confirmed_at_utc + INTERVAL '15 minutes' AND execution_hash IS NOT NULL AND execution_hash ~ '^[A-F0-9]{64}$')");
                table.HasCheckConstraint("ck_container_acl_phase", "(state NOT IN ('Ready','Pending','Applying','Unknown','Succeeded','Superseded','Acknowledged') OR plan_json IS NOT NULL) AND (state NOT IN ('Pending','Applying','Unknown','Succeeded','Superseded','Acknowledged') OR execution_job_id IS NOT NULL) AND (state NOT IN ('Queued','Planning','Ready') OR execution_job_id IS NULL)");
                table.HasCheckConstraint("ck_container_acl_barrier", "(NOT publish_barrier OR (completed_at_utc IS NULL AND root_started_at_utc IS NOT NULL AND execution_job_id IS NOT NULL)) AND (root_started_at_utc IS NULL OR execution_job_id IS NOT NULL AND (publish_barrier OR completed_at_utc IS NOT NULL)) AND (state <> 'Applying' OR publish_barrier)");
                table.HasCheckConstraint("ck_container_acl_result", "(state NOT IN ('Succeeded','Superseded') OR published_version IS NOT NULL AND root_started_at_utc IS NOT NULL AND acl_confirmed IS TRUE AND history_verified AND history_may_exist) AND (published_version IS NULL OR state IN ('Succeeded','Superseded','Acknowledged'))");
                table.HasCheckConstraint("ck_container_acl_facts", "(NOT history_verified OR history_may_exist AND history_digest IS NOT NULL) AND ((history_digest IS NOT NULL) = history_verified) AND (history_digest IS NULL OR history_digest ~ '^[A-F0-9]{64}$') AND (execution_job_id IS NOT NULL OR acl_confirmed IS NULL AND NOT history_may_exist AND NOT history_verified AND history_digest IS NULL) AND (root_started_at_utc IS NOT NULL OR acl_confirmed IS NOT TRUE AND NOT history_may_exist AND NOT history_verified AND history_digest IS NULL) AND (execution_job_id IS NULL OR state NOT IN ('Failed','Canceled') OR acl_confirmed IS FALSE)");
                table.HasCheckConstraint("ck_container_acl_lease", "(lease_token IS NULL) = (lease_expires_at_utc IS NULL)");
                table.HasCheckConstraint("ck_container_acl_ack", "(state = 'Acknowledged') = (acknowledged_by IS NOT NULL AND acknowledgement_json IS NOT NULL) AND (acknowledged_by IS NULL) = (acknowledgement_json IS NULL) AND (acknowledgement_json IS NULL OR receipt_json IS NOT NULL AND octet_length(acknowledgement_json) BETWEEN 1 AND 32768)");
            });
            entity.HasKey(r => r.Id);
            entity.Property(r => r.ActorSubject).HasMaxLength(256); entity.Property(r => r.AcknowledgedBy).HasMaxLength(256);
            entity.Property(r => r.TraceId).HasMaxLength(128); entity.Property(r => r.ContainerId).HasMaxLength(64); entity.Property(r => r.InstanceId).HasMaxLength(64);
            entity.Property(r => r.RelativePath).HasMaxLength(4096);
            entity.Property(r => r.ReceiptJson).HasColumnType("text");
            entity.Property(r => r.CommandJson).HasColumnType("text"); entity.Property(r => r.PlanJson).HasColumnType("text"); entity.Property(r => r.AcknowledgementJson).HasColumnType("text");
            entity.Property(r => r.State).HasMaxLength(16); entity.Property(r => r.ResultCode).HasMaxLength(64); entity.Property(r => r.Version).IsConcurrencyToken();
            foreach (var name in new[] { nameof(ContainerAclIntent.LoginBinding), nameof(ContainerAclIntent.OwnerHash), nameof(ContainerAclIntent.RequestHash),
                nameof(ContainerAclIntent.ReceiptHash), nameof(ContainerAclIntent.PlanHash), nameof(ContainerAclIntent.ExecutionHash), nameof(ContainerAclIntent.PublishedVersion), nameof(ContainerAclIntent.HistoryDigest) }) entity.Property(name).HasMaxLength(64);
            entity.HasIndex(r => new { r.ActorSubject, r.IdempotencyKey }).IsUnique();
            entity.HasIndex(r => r.ExecutionJobId).IsUnique().HasFilter("execution_job_id IS NOT NULL");
            entity.HasIndex(r => r.LeaseToken).IsUnique().HasFilter("lease_token IS NOT NULL");
            entity.HasIndex(r => new { r.ContainerId, r.CompletedAtUtc });
            entity.HasIndex(r => new { r.NextAttemptAtUtc, r.Id }).HasFilter("completed_at_utc IS NULL");
            entity.HasIndex(r => r.PublishBarrier).IsUnique().HasFilter("publish_barrier");
            entity.HasOne<OperationJob>().WithMany().HasForeignKey(r => r.Id).OnDelete(DeleteBehavior.Restrict);
            entity.HasOne<OperationJob>().WithMany().HasForeignKey(r => r.ExecutionJobId).OnDelete(DeleteBehavior.Restrict);
        });
    }
}
